import{_ as s,o as i,c as t,ag as n}from"./chunks/framework.C9sp7nFj.js";const b=JSON.parse('{"title":"SetVibrationParam 加载振动抑制参数","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetVibrationParam.md","filePath":"3. 指令/5. 设置指令/SetVibrationParam.md","lastUpdated":1778862643000}'),e={name:"3. 指令/5. 设置指令/SetVibrationParam.md"};function r(l,a,h,p,d,o){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="setvibrationparam-加载振动抑制参数" tabindex="-1">SetVibrationParam 加载振动抑制参数 <a class="header-anchor" href="#setvibrationparam-加载振动抑制参数" aria-label="Permalink to &quot;SetVibrationParam 加载振动抑制参数&quot;">​</a></h1><p>该指令用于将特定的振动抑制自学习结果加载到当前运动任务中。通过调用预先生成的自学习参数，系统可以针对特定负载和路径下的谐振进行精准补偿，从控制底层解决机械末端在高速运行或频繁启停时产生的抖动问题。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetVibrationParam(Vibrationparam) SetVibrationParam(自学习参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Vibrationparam (自学习参数)</td><td>VIBRATIONPARAM 变量</td><td>存放自学习 ID 号或参数组。该变量存储了系统通过前期自动采样识别出的机械谐振频率、幅值及相应的相位补偿数据。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>机器人在携带负载运动时，其机械结构存在固有的谐振频率。该指令通过加载自学习获得的参数，在伺服控制器的力矩指令中叠加一个反向的补偿信号。当机器人产生抖动倾向时，补偿信号会产生一个相位相反的力矩来抵消机械振动，从而实现末端的平稳运行。</p><hr><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设 VIB1 是通过自学习功能获取并生成的参数组</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetVibrationParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(VIB1)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 加载参数后执行运动，系统将应用针对性的抑振算法</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="执行结果" tabindex="-1">执行结果 <a class="header-anchor" href="#执行结果" aria-label="Permalink to &quot;执行结果&quot;">​</a></h2><p>指令执行后，指定的自学习 ID 将立即生效。后续的运动轨迹在启动和停止阶段的残余振动将显著降低，原本可能出现的低频晃动或高频啸叫会得到有效抑制，机器人运行声音更加平滑。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>复杂工装抑振</strong>：当机器人末端搭载了细长、易晃动的非标准工装时，标准抑振功能往往效果有限，此时需调用自学习参数进行精准补偿。</li><li><strong>变负载工况</strong>：如果生产线上需要处理多种重量差异较大的产品，可以在切换产品后，通过程序调用对应的抑振参数组，确保每种负载下都拥有最佳的动态表现。</li><li><strong>高精度循迹</strong>：在激光焊接或高精度涂胶等对轨迹平滑度要求极高的场景中，通过调用标定好的参数来消除轨迹中的微小波动。</li></ul>`,19)])])}const c=s(e,[["render",r]]);export{b as __pageData,c as default};
